tw.local.ValidationMessage="";
tw.local.errorMessage="";

tw.local.AccountNumber = new tw.object.AccountNumber();
tw.local.AccountNumber.AccNo = tw.local.accountNO;

////To be delleted ..this condition is only for setted only for testing 
//if(tw.local.accountName == null || tw.local.accountName == "")
//	tw.local.accountName= "Test Name - Somaia Galal";

if (tw.local.isSuccessful == false || tw.local.GetAccDetailsResult == null) {
	tw.local.ValidationMessage = "Not Valid Account Number";
	tw.local.accountName = "";
	
}
//else if (tw.local.GetAccDetailsResult.Currencycode != tw.local.liquidationCurrency) {
//	tw.local.ValidationMessage = "Liquidation Currency Not Equal Account Currency";
//	tw.local.accountName = "";
//	
//}
else{
	tw.local.accountName = tw.local.GetAccDetailsResult.AccountDesc;
	tw.local.NostriVostroAccountCurrancy = tw.local.GetAccDetailsResult.Currencycode;
}

